export type ImportedVocabularyCategory = keyof typeof IMPORTED_TAGS_BY_CATEGORY

export function normalizeImportedVocabularyWord(word: string) {
  return word.replace(/\s*\([^)]*\)\s*/g, '').replace(/／/g, '/').trim()
}

export function getImportedVocabularyMetadata(word: string) {
  return IMPORTED_VOCABULARY_METADATA[normalizeImportedVocabularyWord(word) as keyof typeof IMPORTED_VOCABULARY_METADATA]
}
